/* ------------------------------------------------------------------ *
 *  i18n.tsx — smartLAB multi-language support
 *
 *  English is the primary / fallback language.
 *  Supported: EN · AR · RU · DE · ZH · JA · FR
 *
 *  Usage:
 *    const { t, lang, setLang, dir } = useLang();
 *    <span>{t("nav.telemetry")}</span>
 * ------------------------------------------------------------------ */

