export type LangCode = "en" | "ar" | "ru" | "de" | "zh" | "ja" | "fr";

export interface LangMeta {
  code: LangCode;
  label: string;     // native name shown in the dropdown
  flag: string;      // emoji flag
  dir: "ltr" | "rtl";
}

